{"command":"mkdir -p /workspace/src; cd /workspace/src; ls; cp /tmp/help_consts.rs /workspace/src/help_text.rs; cat > /workspace/src/args.rs <<'EOF'
//! Command line interface definition.

use crate::help_text::{AFTER_HELP, AFTER_LONG_HELP, LONG_ABOUT};
use clap::{
    builder::{PossibleValue, PossibleValuesParser, TypedValueParser},
    value_parser, Arg, ArgAction, ArgMatches, Command,
};
use std::{ffi::OsString, num::NonZeroUsize};

pub const ABOUT: &str = "Summarize disk usage of the set of files, recursively for directories.";

/// How to display the numbers of bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

/// Aspect of the files/directories to be measured.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

/// Maximum depth of the tree.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Depth {
    Infinite,
    Finite(NonZeroUsize),
}

/// Number of threads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Threads {
    Auto,
    Max,
    Fixed(NonZeroUsize),
}

/// Parsed command line arguments.
#[derive(Debug, Clone)]
pub struct Args {
    pub files: Vec<OsString>,
    pub json_input: bool,
    pub json_output: bool,
    pub bytes_format: BytesFormat,
    pub deduplicate_hardlinks: bool,
    pub top_down: bool,
    pub align_right: bool,
    pub quantity: Quantity,
    pub max_depth: Depth,
    pub total_width: Option<usize>,
    pub column_width: Option<Vec<usize>>,
    pub min_ratio: f32,
    pub no_sort: bool,
    pub silent_errors: bool,
    pub progress: bool,
    #[allow(dead_code)]
    pub threads: Threads,
    pub omit_json_shared_details: bool,
    pub omit_json_shared_summary: bool,
}

fn parse_depth(text: &str) -> Result<Depth, String> {
    let text = text.trim();
    if text == "inf" {
        return Ok(Depth::Infinite);
    }
    text.parse::<NonZeroUsize>()
        .map(Depth::Finite)
        .map_err(|error| format!("Value is neither \"inf\" nor a positive integer: {error}"))
}

fn parse_threads(text: &str) -> Result<Threads, String> {
    let text = text.trim();
    match text {
        "auto" => return Ok(Threads::Auto),
        "max" => return Ok(Threads::Max),
        _ => {}
    }
    text.parse::<NonZeroUsize>()
        .map(Threads::Fixed)
        .map_err(|error| format!("Value is neither \"auto\", \"max\", nor a number: {error}"))
}

fn parse_min_ratio(text: &str) -> Result<f32, String> {
    let value: f32 = text.parse().map_err(|error| format!("{error}"))?;
    if value < 0.0 {
        return Err("less than 0".to_string());
    }
    if value >= 1.0 {
        return Err("greater than or equal to 1".to_string());
    }
    Ok(value)
}

fn bytes_format_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("plain").help("Display plain number of bytes without units"),
        PossibleValue::new("metric")
            .help("Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on"),
        PossibleValue::new("binary")
            .help("Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on"),
    ]
}

fn quantity_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("apparent-size").help("Measure apparent sizes"),
        PossibleValue::new("block-size").help("Measure block sizes (block-count * 512B)"),
        PossibleValue::new("block-count").help("Count numbers of blocks"),
    ]
}

/// Build the command line interface.
pub fn command() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .after_help(AFTER_HELP)
        .after_long_help(AFTER_LONG_HELP)
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .help("List of files and/or directories")
                .action(ArgAction::Append)
                .value_parser(value_parser!(OsString)),
        )
        .arg(
            Arg::new("json_input")
                .long("json-input")
                .help("Read JSON data from stdin")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["quantity", "deduplicate_hardlinks"]),
        )
        .arg(
            Arg::new("json_output")
                .long("json-output")
                .help("Print JSON data instead of an ASCII chart")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("bytes_format")
                .short('b')
                .long("bytes-format")
                .value_name("BYTES_FORMAT")
                .help("How to display the numbers of bytes")
                .action(ArgAction::Set)
                .default_value("metric")
                .value_parser(PossibleValuesParser::new(bytes_format_values()).map(|s| {
                    match s.as_str() {
                        "plain" => BytesFormat::Plain,
                        "binary" => BytesFormat::Binary,
                        _ => BytesFormat::Metric,
                    }
                })),
        )
        .arg(
            Arg::new("deduplicate_hardlinks")
                .short('H')
                .long("deduplicate-hardlinks")
                .visible_aliases(["detect-links", "dedupe-links"])
                .help(
                    "Detect and subtract the sizes of hardlinks from their parent directory totals",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("top_down")
                .long("top-down")
                .help("Print the tree top-down instead of bottom-up")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("align_right")
                .long("align-right")
                .help("Set the root of the bars to the right")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("quantity")
                .short('q')
                .long("quantity")
                .value_name("QUANTITY")
                .help("Aspect of the files/directories to be measured")
                .action(ArgAction::Set)
                .default_value("block-size")
                .value_parser(PossibleValuesParser::new(quantity_values()).map(|s| {
                    match s.as_str() {
                        "apparent-size" => Quantity::ApparentSize,
                        "block-count" => Quantity::BlockCount,
                        _ => Quantity::BlockSize,
                    }
                })),
        )
        .arg(
            Arg::new("max_depth")
                .short('d')
                .long("max-depth")
                .visible_alias("depth")
                .value_name("MAX_DEPTH")
                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
                .action(ArgAction::Set)
                .default_value("10")
                .value_parser(parse_depth),
        )
        .arg(
            Arg::new("total_width")
                .short('w')
                .long("total-width")
                .visible_alias("width")
                .value_name("TOTAL_WIDTH")
                .help("Width of the visualization")
                .action(ArgAction::Set)
                .value_parser(value_parser!(usize))
                .conflicts_with("column_width"),
        )
        .arg(
            Arg::new("column_width")
                .long("column-width")
                .value_names(["TREE_WIDTH", "BAR_WIDTH"])
                .num_args(2)
                .help("Maximum widths of the tree column and width of the bar column")
                .action(ArgAction::Append)
                .value_parser(value_parser!(usize)),
        )
        .arg(
            Arg::new("min_ratio")
                .short('m')
                .long("min-ratio")
                .value_name("MIN_RATIO")
                .help("Minimal size proportion required to appear")
                .action(ArgAction::Set)
                .default_value("0.01")
                .value_parser(parse_min_ratio),
        )
        .arg(
            Arg::new("no_sort")
                .long("no-sort")
                .help("Do not sort the branches in the tree")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("silent_errors")
                .short('s')
                .long("silent-errors")
                .visible_alias("no-errors")
                .help("Prevent filesystem error messages from appearing in stderr")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .help("Report progress being made at the expense of performance")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .value_name("THREADS")
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
                .action(ArgAction::Set)
                .default_value("auto")
                .value_parser(parse_threads),
        )
        .arg(
            Arg::new("omit_json_shared_details")
                .long("omit-json-shared-details")
                .help("Do not output `.shared.details` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json_output")
                .requires("deduplicate_hardlinks"),
        )
        .arg(
            Arg::new("omit_json_shared_summary")
                .long("omit-json-shared-summary")
                .help("Do not output `.shared.summary` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires("json_output")
                .requires("deduplicate_hardlinks"),
        )
}

impl Args {
    /// Parse the command line arguments of the process.
    pub fn parse() -> Self {
        let matches = command().get_matches();
        Self::from_matches(&matches)
    }

    fn from_matches(matches: &ArgMatches) -> Self {
        let flag = |id: &str| matches.get_flag(id);
        Args {
            files: matches
                .get_many::<OsString>("files")
                .map(|values| values.cloned().collect())
                .unwrap_or_default(),
            json_input: flag("json_input"),
            json_output: flag("json_output"),
            bytes_format: *matches.get_one::<BytesFormat>("bytes_format").unwrap(),
            deduplicate_hardlinks: flag("deduplicate_hardlinks"),
            top_down: flag("top_down"),
            align_right: flag("align_right"),
