//! Command line interface definition.

use crate::help_text::{AFTER_HELP, AFTER_LONG_HELP, LONG_ABOUT};
use clap::{
    builder::{PossibleValue, PossibleValuesParser, TypedValueParser},
    value_parser, Arg, ArgAction, ArgMatches, Command,
};
use std::{ffi::OsString, num::NonZeroUsize};

pub const ABOUT: &str = "Summarize disk usage of the set of files, recursively for directories.";

/// How to display the numbers of bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

/// Aspect of the files/directories to be measured.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

/// Maximum depth of the tree.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Depth {
    Infinite,
    Finite(NonZeroUsize),
}

/// Number of threads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Threads {
    Auto,
    Max,
    Fixed(NonZeroUsize),
}

/// Parsed command line arguments.
#[derive(Debug, Clone)]
pub struct Args {
    pub files: Vec<OsString>,
    pub json_input: bool,
    pub json_output: bool,
    pub bytes_format: BytesFormat,
    pub deduplicate_hardlinks: bool,
    pub top_down: bool,
    pub align_right: bool,
    pub quantity: Quantity,
    pub max_depth: Depth,
    pub total_width: Option<usize>,
    pub column_width: Option<Vec<usize>>,
    pub min_ratio: f32,
    pub no_sort: bool,
    pub silent_errors: bool,
    pub progress: bool,
    #[allow(dead_code)]
    pub threads: Threads,
    pub omit_json_shared_details: bool,
    pub omit_json_shared_summary: bool,
}

fn parse_depth(text: &str) -> Result<Depth, String> {
    let text = text.trim();
    if text == "inf" {
        return Ok(Depth::Infinite);
    }
    text.parse::<NonZeroUsize>()
        .map(Depth::Finite)
        .map_err(|error| format!("Value is neither \"inf\" nor a positive integer: {error}"))
}

fn parse_threads(text: &str) -> Result<Threads, String> {
    let text = text.trim();
    match text {
        "auto" => return Ok(Threads::Auto),
        "max" => return Ok(Threads::Max),
        _ => {}
    }
    text.parse::<NonZeroUsize>()
        .map(Threads::Fixed)
        .map_err(|error| format!("Value is neither \"auto\", \"max\", nor a number: {error}"))
}

fn parse_min_ratio(text: &str) -> Result<f32, String> {
    let value: f32 = text.parse().map_err(|error| format!("{error}"))?;
    if value < 0.0 {
        return Err("less than 0".to_string());
    }
    if value >= 1.0 {
        return Err("greater than or equal to 1".to_string());
    }
    Ok(value)
}

fn bytes_format_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("plain").help("Display plain number of bytes without units"),
        PossibleValue::new("metric")
            .help("Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on"),
        PossibleValue::new("binary")
            .help("Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on"),
    ]
}

fn quantity_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("apparent-size").help("Measure apparent sizes"),
        PossibleValue::new("block-size").help("Measure block sizes (block-count * 512B)"),
        PossibleValue::new("block-count").help("Count numbers of blocks"),
    ]
}

/// Build the command line interface.
pub fn command() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .after_help(AFTER_HELP)
        .after_long_help(AFTER_LONG_HELP)
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .help("List of files and/or directories")
                .action(ArgAction::Append)
                .value_parser(value_parser!(OsString)),
        )
        .arg(
            Arg::new("json_input")
                .long("json-input")
                .help("Read JSON data from stdin")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["quantity", "deduplicate_hardlinks"]),
        )
        .arg(
            Arg::new("json_output")
                .long("json-output")
                .help("Print JSON data instead of an ASCII chart")
                .action(ArgAction::SetTrue),
        )
        .arg(
