                .short('b')
                .long("bytes-format")
                .value_name("BYTES_FORMAT")
                .help("How to display the numbers of bytes")
                .action(ArgAction::Set)
                .default_value("metric")
                .value_parser(PossibleValuesParser::new(bytes_format_values()).map(|s| {
                    match s.as_str() {
