                .help("Print the tree top-down instead of bottom-up")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("align_right")
                .long("align-right")
                .help("Set the root of the bars to the right")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("quantity")
                .short('q')
                .long("quantity")
                .value_name("QUANTITY")
                .help("Aspect of the files/directories to be measured")
                .action(ArgAction::Set)
                .default_value("block-size")
                .value_parser(PossibleValuesParser::new(quantity_values()).map(|s| {
                    match s.as_str() {
                        "apparent-size" => Quantity::ApparentSize,
                        "block-count" => Quantity::BlockCount,
                        _ => Quantity::BlockSize,
                    }
                })),
        )
        .arg(
            Arg::new("max_depth")
                .short('d')
                .long("max-depth")
                .visible_alias("depth")
                .value_name("MAX_DEPTH")
                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
                .action(ArgAction::Set)
                .default_value("10")
                .value_parser(parse_depth),
