//! Formatting of sizes.

use crate::args::BytesFormat;

const UNITS: [char; 5] = ['K', 'M', 'G', 'T', 'P'];

/// Format a number of bytes according to the chosen format.
pub fn format_bytes(value: u64, format: BytesFormat) -> String {
    match format {
        BytesFormat::Plain => value.to_string(),
        BytesFormat::Metric => scaled(value, 1000),
        BytesFormat::Binary => scaled(value, 1024),
    }
}

fn scaled(value: u64, base: u64) -> String {
    if value < base {
        return format!("{value}   ");
    }
    let mut scale = base;
    let mut index = 0;
    while index + 1 < UNITS.len() {
        let next = scale * base;
        if value < next {
