//! Emulation of the messages printed by the panic handler.

use std::io::Write;

const NOTE: &str = "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace";

/// Print a panic-like message for the main thread and exit with code 101.
pub fn panic_at(location: &str, message: &str) -> ! {
    let stderr = std::io::stderr();
    let mut stderr = stderr.lock();
    let _ = write!(
        stderr,
        "\nthread 'main' panicked at {location}:\n{message}\n{NOTE}\n"
    );
    let _ = stderr.flush();
    std::process::exit(101);
}

/// Install a panic hook that mimics the classic panic message format.
pub fn install_hook() {
    std::panic::set_hook(Box::new(|info| {
        let message = if let Some(text) = info.payload().downcast_ref::<&str>() {
            text.to_string()
        } else if let Some(text) = info.payload().downcast_ref::<String>() {
            text.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let location = info
            .location()
            .map(|location| {
                format!(
                    "{}:{}:{}",
                    location.file(),
                    location.line(),
                    location.column()
                )
            })
            .unwrap_or_default();
        let thread = std::thread::current();
        let name = thread.name().unwrap_or("<unnamed>");
        let stderr = std::io::stderr();
        let mut stderr = stderr.lock();
        let _ = write!(
            stderr,
            "\nthread '{name}' panicked at {location}:\n{message}\n{NOTE}\n"
        );
    }));
}

/// Write to stdout, emulating the panic of `print!` on failure.
pub fn print_stdout(text: &str) {
    let stdout = std::io::stdout();
    let mut stdout = stdout.lock();
    if let Err(error) = stdout.write_all(text.as_bytes()) {
        drop(stdout);
        panic_at(
            "library/std/src/io/stdio.rs:1165:9",
            &format!("failed printing to stdout: {error}"),
        );
    }
}

/// Flush stdout, emulating the panic of `print!` on failure.
pub fn flush_stdout() {
    let stdout = std::io::stdout();
    let mut stdout = stdout.lock();
    if let Err(error) = stdout.flush() {
        drop(stdout);
        panic_at(
            "library/std/src/io/stdio.rs:1165:9",
            &format!("failed printing to stdout: {error}"),
        );
    }
}
