//! The data tree and its transformations.

use std::ffi::OsString;

/// A node of the disk usage tree.
#[derive(Debug, Clone)]
pub struct Node {
    pub name: OsString,
    pub size: u64,
    pub children: Vec<Node>,
}

impl Node {
    /// Create a node without children.
    pub fn leaf(name: OsString, size: u64) -> Self {
        Node {
            name,
            size,
            children: Vec::new(),
        }
    }

    /// Create a node whose size is its own size plus the sizes of its children.
    pub fn dir(name: OsString, own_size: u64, children: Vec<Node>) -> Self {
        let size = children
            .iter()
            .fold(own_size, |total, child| total.wrapping_add(child.size));
        Node {
            name,
            size,
            children,
        }
    }

    /// Remove descendants whose sizes are below `min_ratio` of the root's size.
    pub fn cull_insignificant(&mut self, min_ratio: f32) {
        let minimal = self.size as f32 * min_ratio;
        fn retain(node: &mut Node, minimal: f32) {
            node.children.retain(|child| child.size as f32 >= minimal);
            for child in &mut node.children {
                retain(child, minimal);
            }
        }
        retain(self, minimal);
    }

    /// Remove descendants deeper than `max_depth` (the root has depth 1).
    pub fn limit_depth(&mut self, max_depth: usize) {
        fn limit(node: &mut Node, remaining: usize) {
            if remaining <= 1 {
                node.children.clear();
                return;
            }
            for child in &mut node.children {
                limit(child, remaining - 1);
            }
        }
        limit(self, max_depth);
    }

    /// Sort children by size, descending, recursively.
    pub fn sort_by_size(&mut self) {
        self.children.sort_by(|a, b| b.size.cmp(&a.size));
        for child in &mut self.children {
            child.sort_by_size();
        }
    }
}

/// Turn a name into displayable text.
pub fn display_name(name: &OsString) -> String {
    match name.to_str() {
        Some(text) => text.to_string(),
        None => format!("{name:?}"),
    }
}
