/// Shared state of the reporter.
pub struct Reporter {
    silent_errors: bool,
    scanned_items: AtomicU64,
    scanned_total: AtomicU64,
    errors: AtomicU64,
    line_width: Mutex<usize>,
    finished: AtomicBool,
}

impl Reporter {
    pub fn new(silent_errors: bool) -> Arc<Self> {
        Arc::new(Reporter {
            silent_errors,
            scanned_items: AtomicU64::new(0),
            scanned_total: AtomicU64::new(0),
            errors: AtomicU64::new(0),
            line_width: Mutex::new(0),
            finished: AtomicBool::new(false),
        })
    }

    fn clear_line(stderr: &mut impl Write, line_width: &mut usize) {
        let _ = write!(stderr, "\r{}\r", " ".repeat(*line_width));
        *line_width = 0;
    }

    /// Record that an item has been scanned.
    pub fn scanned(&self, size: u64) {
        self.scanned_items.fetch_add(1, Ordering::Relaxed);
        self.scanned_total.fetch_add(size, Ordering::Relaxed);
    }

    /// Report an error that occurred while scanning.
    pub fn error(&self, operation: &str, path: &Path, error: &io::Error) {
        self.errors.fetch_add(1, Ordering::Relaxed);
        if self.silent_errors {
            return;
        }
        let mut line_width = self.line_width.lock().unwrap_or_else(|e| e.into_inner());
        let stderr = io::stderr();
        let mut stderr = stderr.lock();
        Self::clear_line(&mut stderr, &mut line_width);
        let _ = writeln!(stderr, "[error] {operation} {path:?}: {error}");
    }

    fn report_progress(&self) {
        let mut line_width = self.line_width.lock().unwrap_or_else(|e| e.into_inner());
        if self.finished.load(Ordering::SeqCst) {
            return;
        }
        let items = self.scanned_items.load(Ordering::Relaxed);
        let total = self.scanned_total.load(Ordering::Relaxed);
        let errors = self.errors.load(Ordering::Relaxed);
        let text = if errors == 0 {
