        let mut stderr = stderr.lock();
        Self::clear_line(&mut stderr, &mut line_width);
        let _ = write!(stderr, "{text}");
        *line_width = text.len();
    }

    /// Start a thread that periodically reports progress.
    pub fn spawn_progress(self: &Arc<Self>) -> thread::JoinHandle<()> {
        let reporter = Arc::clone(self);
        thread::spawn(move || loop {
            thread::park_timeout(PROGRESS_INTERVAL);
            if reporter.finished.load(Ordering::SeqCst) {
                break;
            }
            reporter.report_progress();
        })
    }

