//! Detection and accounting of hardlinks.

use crate::{bytes_format::SizeDisplay, fatal, tree::Node};
use std::{
    collections::HashMap,
    fmt::Write as _,
    path::{Path, PathBuf},
};

/// Information about a single inode with multiple links.
#[derive(Debug, Clone)]
pub struct Record {
    pub ino: u64,
    pub size: u64,
    pub links: u64,
    /// Every path at which the inode was encountered, in order, including duplicates.
    pub paths: Vec<PathBuf>,
}

impl Record {
    /// Unique paths, in the order they were first encountered.
    pub fn unique_paths(&self) -> Vec<PathBuf> {
        let mut seen = std::collections::HashSet::new();
        let mut result = Vec::new();
        for path in &self.paths {
            if seen.insert(path.as_path()) {
                result.push(path.clone());
            }
        }
        result
    }
}

/// Collection of hardlink records.
#[derive(Debug, Default)]
pub struct Recorder {
    index: HashMap<u64, usize>,
    records: Vec<Record>,
}

impl Recorder {
    pub fn add(&mut self, ino: u64, size: u64, links: u64, path: PathBuf) {
        match self.index.get(&ino) {
            Some(&position) => self.records[position].paths.push(path),
            None => {
                self.index.insert(ino, self.records.len());
                self.records.push(Record {
                    ino,
                    size,
                    links,
                    paths: vec![path],
                });
            }
        }
    }

    /// Records sorted by inode number.
    pub fn into_records(self) -> Vec<Record> {
        let mut records = self.records;
        records.sort_by_key(|record| record.ino);
        records
    }
}

/// Where the root of the tree is located.
pub enum RootPath<'a> {
    /// The root corresponds to a single path.
    Single(&'a Path),
    /// The root is a virtual node whose children correspond to the given paths.
    Total(&'a [PathBuf]),
}

/// Subtract the sizes of duplicated hardlinks from the nodes containing them.
pub fn deduplicate(root: &mut Node, root_path: RootPath, records: &[Record]) {
    // For every ancestor path of every link, count how many links of each inode it contains.
    let mut counts: HashMap<&Path, HashMap<usize, u64>> = HashMap::new();
    for (index, record) in records.iter().enumerate() {
        if record.paths.len() < 2 {
            continue;
        }
        for path in &record.paths {
            let mut current = Some(path.as_path());
            while let Some(ancestor) = current {
                *counts.entry(ancestor).or_default().entry(index).or_insert(0) += 1;
                current = ancestor.parent();
            }
        }
    }

    fn subtract(node: &mut Node, entry: Option<&HashMap<usize, u64>>, records: &[Record]) {
        if let Some(entry) = entry {
            let mut indices: Vec<_> = entry.iter().collect();
            indices.sort();
            for (&index, &count) in indices {
                if count > 1 {
                    let amount = (count - 1).wrapping_mul(records[index].size);
                    node.size = node.size.wrapping_sub(amount);
                }
            }
        }
    }

    fn walk(
        node: &mut Node,
        path: &Path,
        counts: &HashMap<&Path, HashMap<usize, u64>>,
        records: &[Record],
    ) {
        subtract(node, counts.get(path), records);
        for child in &mut node.children {
            let child_path = path.join(&child.name);
            walk(child, &child_path, counts, records);
        }
    }

    match root_path {
        RootPath::Single(path) => walk(root, path, &counts, records),
        RootPath::Total(paths) => {
            for record in records {
                let count = record.paths.len() as u64;
                if count > 1 {
                    let amount = (count - 1).wrapping_mul(record.size);
                    root.size = root.size.wrapping_sub(amount);
                }
            }
            for (child, path) in root.children.iter_mut().zip(paths.iter()) {
                walk(child, path, &counts, records);
            }
        }
    }
}

/// Summary of the hardlinks.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Summary {
    pub inodes: u64,
    pub exclusive_inodes: u64,
    pub all_links: u64,
    pub detected_links: u64,
    pub exclusive_links: u64,
    pub shared_size: u64,
    pub exclusive_shared_size: u64,
}

impl Summary {
    /// Add the information of a single inode.
    pub fn add(&mut self, size: u64, links: u64, detected: u64) {
        if links < detected {
            fatal::panic_at(
                "src/hardlink/hardlink_list/summary.rs:92:21",
                &format!(
                    "Impossible! Total of nlink ({links}) is less than detected paths ({detected}). Something must have gone wrong!"
                ),
            );
        }
        self.inodes = self.inodes.wrapping_add(1);
        self.all_links = self.all_links.wrapping_add(links);
        self.detected_links = self.detected_links.wrapping_add(detected);
        self.shared_size = self.shared_size.wrapping_add(size);
        if links == detected {
            self.exclusive_inodes = self.exclusive_inodes.wrapping_add(1);
            self.exclusive_links = self.exclusive_links.wrapping_add(detected);
            self.exclusive_shared_size = self.exclusive_shared_size.wrapping_add(size);
        }
    }

    pub fn from_records(records: &[Record]) -> Self {
        let mut summary = Summary::default();
        for record in records {
            summary.add(record.size, record.links, record.paths.len() as u64);
        }
        summary
    }

    /// Render the summary as text (ending with a newline).
    pub fn display(&self, size_display: SizeDisplay) -> String {
        let mut text = String::new();
        if self.inodes == 0 {
            text.push_str("There are no hardlinks.\n");
            return text;
        }
        let size = |value: u64| size_display.format(value);
        text.push_str("Hardlinks detected! ");
        if self.exclusive_inodes == self.inodes {
            text.push_str("No files have links outside this tree\n");
            let _ = writeln!(text, "* Number of shared inodes: {}", self.inodes);
            let _ = writeln!(text, "* Total number of links: {}", self.all_links);
            let _ = writeln!(text, "* Total shared size: {}", size(self.shared_size));
        } else if self.exclusive_inodes == 0 {
            text.push_str("All hardlinks within this tree have links without\n");
            let _ = writeln!(text, "* Number of shared inodes: {}", self.inodes);
            let _ = writeln!(
                text,
                "* Total number of links: {} total, {} detected",
                self.all_links, self.detected_links
            );
            let _ = writeln!(text, "* Total shared size: {}", size(self.shared_size));
        } else {
            text.push_str("Some files have links outside this tree\n");
            let _ = writeln!(
                text,
                "* Number of shared inodes: {} total, {} exclusive",
                self.inodes, self.exclusive_inodes
            );
            let _ = writeln!(
                text,
                "* Total number of links: {} total, {} detected, {} exclusive",
                self.all_links, self.detected_links, self.exclusive_links
            );
            let _ = writeln!(
                text,
                "* Total shared size: {} total, {} exclusive",
                size(self.shared_size),
                size(self.exclusive_shared_size)
            );
        }
        text
    }
}
