//! Scanning of the filesystem.

use crate::{
    args::Quantity,
    hardlink::Recorder,
    reporter::Reporter,
    tree::Node,
};
use std::{
    ffi::OsString,
    fs::{self, Metadata},
    os::unix::fs::MetadataExt,
    path::{Path, PathBuf},
};

/// Measure the size of an item.
fn measure(metadata: &Metadata, quantity: Quantity) -> u64 {
    match quantity {
        Quantity::ApparentSize => metadata.len(),
        Quantity::BlockSize => metadata.blocks().wrapping_mul(512),
        Quantity::BlockCount => metadata.blocks(),
    }
}

/// Filesystem scanner.
pub struct Scanner<'a> {
    pub quantity: Quantity,
    pub reporter: &'a Reporter,
    pub hardlinks: Option<Recorder>,
}

impl Scanner<'_> {
    /// Scan a path recursively and build a tree node named `name`.
    pub fn scan(&mut self, path: &Path, name: OsString) -> Node {
        let metadata = match fs::symlink_metadata(path) {
            Ok(metadata) => metadata,
            Err(error) => {
                self.reporter.error("symlink_metadata", path, &error);
                return Node::leaf(name, 0);
            }
        };
        let size = measure(&metadata, self.quantity);
        self.reporter.scanned(size);
        if !metadata.is_dir() {
            if let Some(recorder) = &mut self.hardlinks {
                let links = metadata.nlink();
                if links > 1 {
                    recorder.add(metadata.ino(), size, links, path.to_path_buf());
                }
            }
            return Node::leaf(name, size);
        }
        let entries = match fs::read_dir(path) {
            Ok(entries) => entries,
            Err(error) => {
                self.reporter.error("read_dir", path, &error);
                return Node::leaf(name, size);
            }
        };
        let mut children = Vec::new();
        for entry in entries {
            match entry {
                Ok(entry) => {
                    let child_path = entry.path();
                    children.push(self.scan(&child_path, entry.file_name()));
                }
                Err(error) => self.reporter.error("access_entry", path, &error),
            }
        }
        Node::dir(name, size, children)
    }
}

/// Remove arguments that are directories contained in (or equal to) other arguments.
pub fn remove_overlapping_paths(paths: Vec<OsString>) -> Vec<OsString> {
    struct Info {
        is_dir: bool,
        canonical: Option<PathBuf>,
    }
    let infos: Vec<Info> = paths
        .iter()
        .map(|path| {
            let is_dir = fs::symlink_metadata(path)
                .map(|metadata| metadata.is_dir())
                .unwrap_or(false);
            let canonical = fs::canonicalize(path).ok();
            Info { is_dir, canonical }
        })
        .collect();
    let overlapped = |index: usize| -> bool {
        let info = &infos[index];
        if !info.is_dir {
            return false;
        }
        let Some(canonical) = &info.canonical else {
            return false;
        };
        infos.iter().enumerate().any(|(other_index, other)| {
            if other_index == index {
                return false;
            }
            let Some(other_canonical) = &other.canonical else {
                return false;
            };
            if canonical == other_canonical {
                other_index < index
            } else {
                canonical.starts_with(other_canonical)
            }
        })
    };
    paths
        .into_iter()
        .enumerate()
        .filter(|(index, _)| !overlapped(*index))
        .map(|(_, path)| path)
        .collect()
}
