pub enum ColumnWidth {
    /// Total width of the chart.
    Total(usize),
    /// Maximum width of the tree column and width of the bar column.
    Components { tree: usize, bar: usize },
}

/// Settings of the chart.
pub struct Visualizer<'a> {
    pub tree: &'a Node,
    pub size_display: SizeDisplay,
    pub top_down: bool,
    pub align_right: bool,
    pub column_width: ColumnWidth,
}

/// Width of everything except the tree and bar columns, excluding the size column:
/// a space, two borders and the percentage column.
const FIXED_WIDTH: usize = 7;
/// Width of the percentage column.
const PERCENTAGE_WIDTH: usize = 4;

struct Row<'a> {
    depth: usize,
    parent: Option<usize>,
    size: u64,
    name: String,
    size_text: String,
    node: &'a Node,
}

struct Rendered {
    /// Rendered names of rows, `None` for excluded rows.
    names: Vec<Option<String>>,
    /// Maximum width of the visible tree cells.
    tree_width: usize,
    /// Whether any row is visible.
    any: bool,
}

fn flatten<'a>(node: &'a Node, depth: usize, parent: Option<usize>, size_display: SizeDisplay, rows: &mut Vec<Row<'a>>) {
    let index = rows.len();
    rows.push(Row {
        depth,
        parent,
        size: node.size,
        name: display_name(&node.name),
        size_text: size_display.format(node.size),
        node,
    });
    for child in &node.children {
        flatten(child, depth + 1, Some(index), size_display, rows);
    }
}

fn render_names(rows: &[Row], max_width: usize) -> Rendered {
    let mut names: Vec<Option<String>> = Vec::with_capacity(rows.len());
    let mut tree_width = 0;
    let mut any = false;
    for row in rows {
        if let Some(parent) = row.parent {
            if names[parent].is_none() {
                names.push(None);
                continue;
            }
        }
        let skeleton = row.depth * 2 + 3;
        let width = skeleton + text_width(&row.name);
        let name = if width <= max_width {
            Some(row.name.clone())
        } else if skeleton + 3 >= max_width {
            None
        } else {
            let new_len = max_width - skeleton - 3;
            let mut name = row.name.clone();
            if !name.is_char_boundary(new_len) {
                fatal::panic_at(
                    "src/visualizer/tree.rs:131:19",
                    "assertion failed: self.is_char_boundary(new_len)",
                );
            }
            name.truncate(new_len);
            name.push_str("...");
            Some(name)
        };
        if let Some(name) = &name {
            any = true;
            tree_width = tree_width.max(skeleton + text_width(name));
        }
        names.push(name);
    }
    Rendered {
        names,
        tree_width,
        any,
    }
}

fn pad_left(text: &str, width: usize) -> String {
    let current = text_width(text);
    if current >= width {
        text.to_string()
    } else {
        let mut result = " ".repeat(width - current);
        result.push_str(text);
        result
    }
}

fn pad_right(text: &str, width: usize) -> String {
    let current = text_width(text);
    if current >= width {
        text.to_string()
    } else {
        let mut result = text.to_string();
        result.push_str(&" ".repeat(width - current));
        result
    }
}

fn ratio(value: u64, multiplier: u64, total: u64) -> u64 {
    if total == 0 {
        return 0;
    }
    let numerator = value.wrapping_mul(multiplier) as f64;
    (numerator / total as f64).round() as u64
}

fn level_char(level: usize) -> char {
    match level {
        0 => ' ',
        1 => '░',
        2 => '▒',
        _ => '▓',
    }
}

impl Visualizer<'_> {
    /// Render the rows of the chart, each without a trailing newline.
    pub fn rows(&self) -> Vec<String> {
        let mut rows = Vec::new();
        flatten(self.tree, 0, None, self.size_display, &mut rows);
        let size_width = rows
            .iter()
            .map(|row| text_width(&row.size_text))
            .max()
            .unwrap_or(0);
        let min_width = size_width + FIXED_WIDTH;

        let components = |tree: usize, bar: usize| (render_names(&rows, tree), bar);
        let (rendered, bar_width) = match self.column_width {
            ColumnWidth::Components { tree, bar } => components(tree, bar),
            ColumnWidth::Total(width) => {
                if width <= min_width {
                    components(min_width, 3)
                } else if width <= 17 {
                    components(min_width, 20)
                } else {
                    let tree_max = width - min_width.max(17);
                    let rendered = render_names(&rows, tree_max);
                    let bar_width = width - min_width - rendered.tree_width;
                    if bar_width == 0 {
                        components(width, 1)
                    } else {
                        (rendered, bar_width)
                    }
                }
            }
        };
        if !rendered.any {
            return Vec::new();
        }
        let names = rendered.names;
        let tree_width = rendered.tree_width;

        // Determine visible structure.
        let count = rows.len();
        let mut is_last = vec![false; count];
        let mut has_children = vec![false; count];
        {
            let mut last_child: Vec<Option<usize>> = vec![None; count];
            for (index, row) in rows.iter().enumerate() {
                if names[index].is_none() {
                    continue;
                }
                match row.parent {
                    Some(parent) => {
                        has_children[parent] = true;
                        last_child[parent] = Some(index);
                    }
                    None => is_last[index] = true,
                }
            }
            for child in last_child.into_iter().flatten() {
                is_last[child] = true;
            }
        }

        let total = self.tree.size;
        let mut lines = Vec::new();
        let mut chain: Vec<usize> = Vec::new();
        for (index, row) in rows.iter().enumerate() {
            let Some(name) = &names[index] else {
                continue;
            };
            // Chain of ancestors from root to this row.
            chain.clear();
            let mut current = Some(index);
            while let Some(position) = current {
                chain.push(position);
                current = rows[position].parent;
            }
            chain.reverse();

            // Tree cell.
            let mut tree_cell = String::new();
            for &ancestor in &chain[..chain.len() - 1] {
                tree_cell.push_str(if is_last[ancestor] { "  " } else { "│ " });
            }
            let (corner, junction) = if self.top_down { ('└', '┬') } else { ('┌', '┴') };
            tree_cell.push(if is_last[index] { corner } else { '├' });
            tree_cell.push('─');
            tree_cell.push(if has_children[index] { junction } else { '─' });
            tree_cell.push_str(name);

            // Bar cell.
            let lengths: Vec<usize> = chain
                .iter()
                .map(|&position| ratio(rows[position].size, bar_width as u64, total) as usize)
                .collect();
            let own_level = chain.len() - 1;
            let mut bar: Vec<char> = Vec::with_capacity(bar_width);
            for position in 0..bar_width {
                let mut ch = ' ';
                if position < lengths[own_level] {
                    ch = '█';
                } else {
                    for level in (0..own_level).rev() {
                        if position < lengths[level] {
                            ch = level_char(level);
                            break;
                        }
                    }
                }
                bar.push(ch);
            }
            if self.align_right {
                bar.reverse();
            }
            let bar: String = bar.into_iter().collect();

            let percentage = format!("{}%", ratio(row.size, 100, total));
            let _ = row.node;
            lines.push(format!(
                "{size} {tree}│{bar}│{percentage}",
                size = pad_left(&row.size_text, size_width),
                tree = pad_right(&tree_cell, tree_width),
                percentage = pad_left(&percentage, PERCENTAGE_WIDTH),
            ));
        }
        if !self.top_down {
            lines.reverse();
        }
        lines
    }
}
EOF
