mod args;
mod bytes_format;
mod fatal;
mod hardlink;
mod help_text;
mod json;
mod reporter;
mod scan;
mod terminal;
mod tree;
mod visualizer;
mod width;

use args::{Args, Depth, Quantity};
use bytes_format::SizeDisplay;
use std::{ffi::OsString, io::Write, path::PathBuf, process::ExitCode};
use tree::Node;
use visualizer::{ColumnWidth, Visualizer};

/// Default width of the chart when the terminal width cannot be determined.
const DEFAULT_WIDTH: usize = 150;

fn main() -> ExitCode {
    fatal::install_hook();
    let args = Args::parse();
    let worker = std::thread::Builder::new()
        .name("main".to_string())
        .stack_size(1 << 30)
        .spawn(move || run(args))
        .expect("spawn main worker");
    match worker.join() {
        Ok(code) => ExitCode::from(code),
        Err(_) => ExitCode::from(101),
    }
}

fn error_exit(name: &str, message: &str, code: u8) -> u8 {
    let stderr = std::io::stderr();
    let mut stderr = stderr.lock();
    let _ = writeln!(stderr, "[error] {name}: {message}");
    code
}

fn column_width(args: &Args) -> ColumnWidth {
    match (args.total_width, &args.column_width) {
        (None, None) => {
            ColumnWidth::Total(terminal::terminal_width().unwrap_or(DEFAULT_WIDTH))
        }
        (Some(width), None) => ColumnWidth::Total(width),
        (None, Some(values)) if values.len() == 2 => ColumnWidth::Components {
            tree: values[0],
            bar: values[1],
        },
        (total_width, column_width) => {
            let stderr = std::io::stderr();
            let mut stderr = stderr.lock();
            let _ = writeln!(
                stderr,
                "[src/args.rs:191:17] total_width = {total_width:#?}"
            );
            let _ = writeln!(
                stderr,
                "[src/args.rs:191:17] column_width = {column_width:#?}"
            );
            drop(stderr);
            fatal::panic_at("src/args.rs:192:17", "Something goes wrong");
        }
    }
}

fn print_chart(args: &Args, tree: &Node, size_display: SizeDisplay) {
    let visualizer = Visualizer {
        tree,
        size_display,
        top_down: args.top_down,
        align_right: args.align_right,
        column_width: column_width(args),
    };
    let rows = visualizer.rows();
    let mut text = String::new();
    for row in rows {
        text.push_str(&row);
        text.push('\n');
    }
    fatal::print_stdout(&text);
    fatal::flush_stdout();
}

fn run(args: Args) -> u8 {
    if args.json_input {
        run_json_input(args)
    } else {
        run_scan(args)
    }
}

fn run_json_input(args: Args) -> u8 {
    if !args.files.is_empty() {
        return error_exit(
            "JsonInputArgConflict",
            "Arguments exist alongside --json-input",
            4,
        );
    }
    let stdin = std::io::stdin();
    let reader = std::io::BufReader::new(stdin.lock());
    let data: json::JsonData = match serde_json::from_reader(reader) {
        Ok(data) => data,
        Err(error) => return error_exit("DeserializationFailure", &error.to_string(), 3),
    };
    let (json_tree, size_display, unit_name) = match data.body {
        json::JsonDataBody::Bytes(tree) => (tree, SizeDisplay::Bytes(args.bytes_format), "Bytes"),
        json::JsonDataBody::Blocks(tree) => (tree, SizeDisplay::Blocks, "Blocks"),
    };
    let json::JsonTree { tree, shared } = json_tree;
    let tree = match json::into_tree(tree) {
        Ok(tree) => tree,
        Err(error) => {
            let message = format!(
                "ExcessiveChildren: {path:?} ({unit_name}({size})) is less than a child named {child:?} ({unit_name}({child_size}))",
                path = error.path,
                size = error.size,
                child = error.child_name,
                child_size = error.child_size,
            );
            return error_exit("InvalidInputReflection", &message, 5);
        }
    };
    print_chart(&args, &tree, size_display);
    let summary = match (shared.summary, shared.details) {
        (Some(summary), _) => Some(hardlink::Summary::from(summary)),
        (None, Some(details)) => {
            let mut summary = hardlink::Summary::default();
            for entry in &details {
                summary.add(entry.size, entry.links, entry.paths.len() as u64);
            }
            Some(summary)
        }
        (None, None) => None,
    };
    if let Some(summary) = summary {
        let mut text = summary.display(size_display);
        text.push('\n');
        fatal::print_stdout(&text);
        fatal::flush_stdout();
    }
    0
}

fn run_scan(args: Args) -> u8 {
    let size_display = match args.quantity {
        Quantity::BlockCount => SizeDisplay::Blocks,
        _ => SizeDisplay::Bytes(args.bytes_format),
    };
    let mut files: Vec<OsString> = if args.files.is_empty() {
        vec![OsString::from(".")]
    } else {
        args.files.clone()
    };
    if args.deduplicate_hardlinks {
        files = scan::remove_overlapping_paths(files);
    }

    let reporter = reporter::Reporter::new(args.silent_errors);
    if args.progress {
        reporter.spawn_progress();
    }
    let mut scanner = scan::Scanner {
        quantity: args.quantity,
        reporter: &reporter,
        hardlinks: args
            .deduplicate_hardlinks
            .then(hardlink::Recorder::default),
    };
    let is_total = files.len() != 1;
    let mut root = if is_total {
        let children: Vec<Node> = files
            .iter()
            .map(|file| scanner.scan(&PathBuf::from(file), file.clone()))
            .collect();
        Node::dir(OsString::from("(total)"), 0, children)
    } else {
        let file = &files[0];
        scanner.scan(&PathBuf::from(file), file.clone())
    };
    reporter.finish();
    let records = scanner.hardlinks.take().map(hardlink::Recorder::into_records);

    root.cull_insignificant(args.min_ratio);
    if let Depth::Finite(depth) = args.max_depth {
        root.limit_depth(depth.get());
    }
    if !args.no_sort {
        root.sort_by_size();
    }
    if let Some(records) = &records {
        hardlink::deduplicate(&mut root, is_total, records);
    }

    if args.json_output {
        let summary = records
            .as_ref()
            .filter(|records| !records.is_empty())
            .map(|records| hardlink::Summary::from_records(records));
        let shared = match &records {
            Some(records) if !records.is_empty() => json::JsonShared {
                details: (!args.omit_json_shared_details).then(|| {
                    records
                        .iter()
                        .map(|record| json::ReflectionEntry {
                            ino: record.ino,
                            size: record.size,
                            links: record.links,
                            paths: record.unique_paths(),
                        })
                        .collect()
                }),
                summary: if args.omit_json_shared_summary {
                    None
                } else {
                    summary.map(json::Summary::from)
                },
            },
            _ => json::JsonShared::default(),
        };
        let json_tree = json::JsonTree {
            tree: json::reflect(&root),
            shared,
        };
        let body = match args.quantity {
            Quantity::BlockCount => json::JsonDataBody::Blocks(json_tree),
            _ => json::JsonDataBody::Bytes(json_tree),
        };
        let data = json::JsonData {
            schema_version: json::SchemaVersion,
            binary_version: Some(json::BINARY_VERSION.to_string()),
            body,
        };
        let stdout = std::io::stdout();
        let mut writer = std::io::BufWriter::new(stdout.lock());
        let _ = serde_json::to_writer(&mut writer, &data);
        let _ = writer.flush();
        return 0;
    }

    print_chart(&args, &root, size_display);
    if let Some(records) = &records {
        if !records.is_empty() {
            let summary = hardlink::Summary::from_records(records);
            fatal::print_stdout(&summary.display(size_display));
            fatal::flush_stdout();
        }
    }
    0
}
