//! Detection of the terminal width.

use std::os::raw::{c_int, c_ulong, c_ushort};

#[repr(C)]
#[derive(Default)]
struct WindowSize {
    rows: c_ushort,
    columns: c_ushort,
    x_pixels: c_ushort,
    y_pixels: c_ushort,
}

extern "C" {
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
}

/// `TIOCGWINSZ` request code on Linux.
const TIOCGWINSZ: c_ulong = 0x5413;

/// Width of the terminal attached to stdout, stderr, or stdin (in that order).
pub fn terminal_width() -> Option<usize> {
    for fd in [1, 2, 0] {
        let mut size = WindowSize::default();
        // SAFETY: `size` is a valid, writable `struct winsize`.
        let result = unsafe { ioctl(fd, TIOCGWINSZ, &mut size as *mut WindowSize) };
        if result == 0 && size.columns > 0 {
            return Some(size.columns as usize);
        }
    }
    None
}
EOF
