//! Display width of text.

use crate::width_table::WIDTH_CORRECTIONS;
use unicode_width::UnicodeWidthStr;

/// Width correction of a single character.
fn correction(ch: char) -> isize {
    let code = ch as u32;
    if code < 0x800 {
        return 0;
    }
    match WIDTH_CORRECTIONS.binary_search_by(|&(start, end, _)| {
        if end < code {
            std::cmp::Ordering::Less
        } else if start > code {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(index) => WIDTH_CORRECTIONS[index].2 as isize,
        Err(_) => 0,
    }
}

/// Width of a segment without line feeds.
fn segment_width(segment: &str) -> usize {
    let base = UnicodeWidthStr::width(segment) as isize;
    let adjusted = segment.chars().map(correction).sum::<isize>() + base;
    adjusted.max(0) as usize
}

/// Compute the display width of a string.
///
/// Line feeds (and carriage return + line feed pairs) are treated as having zero width.
pub fn text_width(text: &str) -> usize {
    if !text.contains('\n') {
        return segment_width(text);
    }
    let mut segments = text.split('\n').peekable();
    let mut total = 0;
    while let Some(segment) = segments.next() {
        let segment = if segments.peek().is_some() {
            segment.strip_suffix('\r').unwrap_or(segment)
        } else {
            segment
        };
        total += segment_width(segment);
    }
    total
}
EOF
